from numbers import Integral

def counts_after_edits(initial, removed=None, added=None):
    """Integer counts for ordered, fully occupied sites; substitutions count as remove+add."""
    removed, added = removed or {}, added or {}
    for mapping in (initial, removed, added):
        if any(isinstance(n, bool) or not isinstance(n, Integral) or n < 0 for n in mapping.values()):
            raise ValueError("Site counts must be nonnegative integers")
    if any(n > initial.get(e, 0) for e, n in removed.items()):
        raise ValueError("Cannot remove more original sites of a species than exist")
    result = {e: initial.get(e, 0) - removed.get(e, 0) + added.get(e, 0)
              for e in set(initial) | set(removed) | set(added)}
    return {e: n for e, n in result.items() if n}
